// Build-time access to data/hadith (generated by scripts/convert-hadith.mjs).
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

const DIR = path.join(process.cwd(), "data", "hadith");

const load = cache(async <T>(file: string): Promise<T> =>
  JSON.parse(await fs.readFile(path.join(DIR, file), "utf8")),
);

export type HadithCollection = {
  id: string;
  nameAr: string;
  nameEn: string;
  authorAr: string;
  authorEn: string;
  gradedByAr?: string;
  gradedByEn?: string;
  noteAr?: string;
  noteEn?: string;
  books: number;
  hadiths: number;
};

export type HadithBook = {
  id: string;
  nameAr: string;
  nameEn: string;
  count: number;
  first: string;
  last: string;
};

export type Hadith = {
  number?: string;
  ar: string;
  en?: string;
  grade?: string;
  chapterAr?: string;
  chapterEn?: string;
};

/** Hadiths per page in a book; keeps the largest Musnad Ahmad books light. */
export const HADITH_PAGE_SIZE = 50;

export const getHadithCollections = () => load<HadithCollection[]>("collections.json");
export const getHadithCollection = async (id: string) =>
  (await getHadithCollections()).find((c) => c.id === id);
export const getHadithBooks = (collection: string) => load<HadithBook[]>(`${collection}/books.json`);
export const getHadithBook = (collection: string, book: string) =>
  load<Hadith[]>(`${collection}/${book}.json`);

/** Every (collection, book) pair, for generateStaticParams. */
export const getAllHadithBooks = cache(async () => {
  const collections = await getHadithCollections();
  const lists = await Promise.all(collections.map((c) => getHadithBooks(c.id)));
  return collections.flatMap((c, i) => lists[i].map((b) => ({ collection: c.id, book: b })));
});

